import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"斜杠命令","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/reference/slash-commands.md","filePath":"zh/kimi-code-cli/reference/slash-commands.md"}`),a={name:`kimi-code-cli/reference/slash-commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to “斜杠命令”">​</a></h1><p>斜杠命令是 Kimi Code CLI 在交互式 TUI 中提供的内置控制命令，涵盖账号配置、会话管理、模式切换、信息查询等操作。在输入框中输入 <code>/</code> 即可触发命令补全，候选列表随后续字符实时过滤；命令的别名也会一并参与匹配。</p><p>输入完整命令名后按 <code>Enter</code> 执行。如果输入的 <code>/</code> 开头内容不匹配任何内置或 Skill 命令，则按普通消息发送给 Agent。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>部分命令仅在空闲（idle）状态下可用。会话正在流式输出或压缩上下文时执行这些命令会被拦截，需先按 <code>Esc</code> 或 <code>Ctrl-C</code> 中断。下表「随时可用」列标注了流式输出期间也可用的命令。</p></div><h2 id="账号与配置" tabindex="-1">账号与配置 <a class="header-anchor" href="#账号与配置" aria-label="Permalink to “账号与配置”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>别名</th><th>说明</th><th>随时可用</th></tr></thead><tbody><tr><td><code>/login</code></td><td>—</td><td>选择账号或平台并登录：Kimi Code 走 OAuth 验证码流程，Kimi Platform 通过 API 密钥登录</td><td>否</td></tr><tr><td><code>/logout</code></td><td>—</td><td>清除当前所选账号的凭据</td><td>否</td></tr><tr><td><code>/provider</code></td><td>—</td><td>打开交互式供应商管理器，查看、添加和删除已配置的供应商。详见<a href="/code/docs/kimi-code-cli/configuration/providers.html#provider-与供应商管理">平台与模型 — <code>/provider</code> 与供应商管理</a></td><td>是</td></tr><tr><td><code>/model</code></td><td>—</td><td>切换当前会话使用的 LLM 模型</td><td>是</td></tr><tr><td><code>/settings</code></td><td><code>/config</code></td><td>打开 TUI 内的设置面板</td><td>是</td></tr><tr><td><code>/experiments</code></td><td><code>/experimental</code></td><td>打开实验功能面板</td><td>是</td></tr><tr><td><code>/permission</code></td><td>—</td><td>选择权限模式</td><td>是</td></tr><tr><td><code>/editor</code></td><td>—</td><td>配置 <code>Ctrl-G</code> 调起的外部编辑器</td><td>是</td></tr><tr><td><code>/theme</code></td><td>—</td><td>切换终端 UI 配色主题</td><td>是</td></tr></tbody></table><h2 id="会话管理" tabindex="-1">会话管理 <a class="header-anchor" href="#会话管理" aria-label="Permalink to “会话管理”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>别名</th><th>说明</th><th>随时可用</th></tr></thead><tbody><tr><td><code>/new</code></td><td><code>/clear</code></td><td>开启全新会话，丢弃当前上下文</td><td>否</td></tr><tr><td><code>/sessions</code></td><td><code>/resume</code></td><td>浏览历史会话并切换/恢复</td><td>否</td></tr><tr><td><code>/tasks</code></td><td><code>/task</code></td><td>浏览后台任务列表</td><td>是</td></tr><tr><td><code>/fork</code></td><td>—</td><td>基于当前会话 fork 一份新会话，保留完整对话历史</td><td>否</td></tr><tr><td><code>/title [&lt;text&gt;]</code></td><td><code>/rename</code></td><td>不带参数时显示当前会话标题；带参数时设置为新标题（最长 200 字符）</td><td>是</td></tr><tr><td><code>/compact [&lt;instruction&gt;]</code></td><td>—</td><td>压缩当前对话上下文，释放 token 占用；可附带自定义指令，提示模型压缩时保留哪些信息</td><td>否</td></tr><tr><td><code>/undo [&lt;count&gt;]</code></td><td>—</td><td>从当前上下文撤销最近的提示词。不带数量时打开选择器；带数量时撤销对应条数。最后一次上下文压缩之前的提示词不能撤销</td><td>否</td></tr><tr><td><code>/init</code></td><td>—</td><td>分析当前代码库并生成 <code>AGENTS.md</code></td><td>否</td></tr><tr><td><code>/export-md [&lt;path&gt;]</code></td><td><code>/export</code></td><td>将当前会话导出为 Markdown 文件</td><td>否</td></tr><tr><td><code>/export-debug-zip</code></td><td>—</td><td>将当前会话导出为调试用 ZIP 压缩包（与 <a href="/code/docs/kimi-code-cli/reference/kimi-command.html#kimi-export"><code>kimi export</code></a> 行为一致）</td><td>否</td></tr><tr><td><code>/copy</code></td><td>—</td><td>将最后一条 AI 回复复制到剪贴板</td><td>否</td></tr><tr><td><code>/add-dir [&lt;path&gt;]</code></td><td>—</td><td>为当前会话添加额外的工作目录。不带路径（或传入 <code>list</code>）运行时列出已配置的目录。添加时可选择是否将目录记入项目的 <code>.kimi-code/local.toml</code></td><td>否</td></tr><tr><td><code>/web</code></td><td>—</td><td>在 web UI 中打开当前会话：选择一个运行中的实例进行连接，或在 TUI 退出后新开一个前台服务器。参见 <a href="/code/docs/kimi-code-cli/reference/kimi-command.html#kimi-web"><code>kimi web</code></a></td><td>是</td></tr></tbody></table><h2 id="模式与运行控制" tabindex="-1">模式与运行控制 <a class="header-anchor" href="#模式与运行控制" aria-label="Permalink to “模式与运行控制”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>别名</th><th>说明</th><th>随时可用</th></tr></thead><tbody><tr><td><code>/yolo [on|off]</code></td><td><code>/yes</code></td><td>切换 YOLO 模式。不带参数时翻转；显式传 <code>on</code>/<code>off</code> 时强制设置。开启后跳过普通工具调用审批；Plan 模式的退出审批不受影响</td><td>是</td></tr><tr><td><code>/auto [on|off]</code></td><td>—</td><td>切换 auto 权限模式。开启后工具审批自动处理，Agent 不会向用户提问</td><td>是</td></tr><tr><td><code>/plan [on|off]</code></td><td>—</td><td>切换 Plan 模式。不带参数时翻转；显式传 <code>on</code>/<code>off</code> 时强制设置。单纯切换不会创建空计划文件</td><td>是</td></tr><tr><td><code>/plan clear</code></td><td>—</td><td>清除当前 plan 方案</td><td>否</td></tr><tr><td><code>/swarm on|off</code></td><td>—</td><td>开启或关闭 swarm mode，但不发送提示词。</td><td>是</td></tr><tr><td><code>/swarm &lt;task&gt;</code></td><td>—</td><td>先开启 swarm mode，再把 <code>&lt;task&gt;</code> 作为普通提示词发送。如果该轮次正常完成，swarm mode 会自动关闭。若当前是 <code>manual</code> 权限模式，启动前会提示是否切换到 <code>auto</code> 或 <code>yolo</code>。</td><td>否</td></tr><tr><td><code>/goal [...]</code></td><td>—</td><td>开始或管理目标模式</td><td>见下文</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">注意</p><p><code>/yolo</code> 会跳过普通工具调用的审批确认，使用前请确保了解可能的风险。Plan 模式的退出审批不会被 <code>/yolo</code> 跳过；Plan 模式下的 <code>Bash</code> 也按 <code>/yolo</code> 的普通放行规则处理。</p></div><h2 id="目标模式" tabindex="-1">目标模式 <a class="header-anchor" href="#目标模式" aria-label="Permalink to “目标模式”">​</a></h2><p><code>/goal</code> 用于开始或管理目标模式：Kimi Code 会在自动续跑的轮次中持续朝一个持久目标工作。使用指导和示例见<a href="/code/docs/kimi-code-cli/guides/goals.html">使用目标模式</a>。</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 更新</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 文档，运行</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build，如果</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 轮后仍被阻塞就停止</span></span></code></pre></div><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>可用性</th></tr></thead><tbody><tr><td><code>/goal</code> 或 <code>/goal status</code></td><td>显示当前目标及其状态、已用时间、轮次数、token 数</td><td>随时可用</td></tr><tr><td><code>/goal pause</code></td><td>暂停当前的目标，但不删除</td><td>随时可用</td></tr><tr><td><code>/goal resume</code></td><td>继续被暂停或被阻塞的目标</td><td>仅空闲时</td></tr><tr><td><code>/goal cancel</code></td><td>移除当前目标</td><td>随时可用</td></tr><tr><td><code>/goal replace &lt;objective&gt;</code></td><td>用新目标替换已保存的目标</td><td>仅空闲时</td></tr><tr><td><code>/goal next &lt;objective&gt;</code></td><td>为当前会话安排一个后续目标。如果当前没有目标，则立即开始它。当前目标完成前，Agent 不会看到已排队的目标</td><td>随时可用</td></tr><tr><td><code>/goal next manage</code></td><td>打开后续目标管理器。用 <kbd>↑</kbd> / <kbd>↓</kbd> 浏览，<kbd>Space</kbd> 选择一个目标以便移动，选中后用 <kbd>↑</kbd> / <kbd>↓</kbd> 调整顺序，<kbd>E</kbd> 编辑，<kbd>D</kbd> 删除，<kbd>Esc</kbd> 取消。编辑输入框中，用 <kbd>Shift-Enter</kbd> 或 <kbd>Ctrl-J</kbd> 添加新行，用 <kbd>Enter</kbd> 保存</td><td>随时可用</td></tr></tbody></table><p><code>status</code>、<code>pause</code>、<code>resume</code>、<code>cancel</code>、<code>replace</code> 和 <code>next</code> 只有作为 <code>/goal</code> 后的第一个词时才是子命令。如果你的目标需要以这些词开头，请在目标前加 <code>--</code>：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cancel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 函数需要在订单失败时返回可重试错误，并补充测试</span></span></code></pre></div><p>如果后续目标需要以 <code>manage</code> 开头，请在 <code>next</code> 后加 <code>--</code>：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 发布检查清单</span></span></code></pre></div><p>在非交互式 prompt 模式中，只有创建形式会启动目标模式：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/goal 修复 checkout 测试失败&quot;</span></span></code></pre></div><p>Prompt 模式在目标完成时以退出码 <code>0</code> 退出，在目标阻塞时以 <code>3</code> 退出，在目标暂停时以 <code>6</code> 退出。其它 <code>/goal</code> 子命令，包括 <code>next</code>，都是 TUI 控制命令，不由 <code>kimi -p</code> 处理。</p><h2 id="信息与状态" tabindex="-1">信息与状态 <a class="header-anchor" href="#信息与状态" aria-label="Permalink to “信息与状态”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>别名</th><th>说明</th><th>随时可用</th></tr></thead><tbody><tr><td><code>/help</code></td><td><code>/h</code>、<code>/?</code></td><td>显示快捷键和所有可用命令</td><td>是</td></tr><tr><td><code>/btw [问题]</code></td><td>—</td><td>在 fork 出的子 Agent 中打开旁路对话，不改变当前主 Agent 轮次；不带问题时会先打开面板等待输入</td><td>是</td></tr><tr><td><code>/usage</code></td><td>—</td><td>显示 token 用量、上下文占用以及配额信息</td><td>是</td></tr><tr><td><code>/status</code></td><td>—</td><td>显示当前会话运行时状态：版本、模型、工作目录、权限模式等</td><td>是</td></tr><tr><td><code>/mcp</code></td><td>—</td><td>列出当前会话中的 MCP server 及连接状态</td><td>是</td></tr><tr><td><code>/plugins</code></td><td>—</td><td>打开交互式 plugin 管理器</td><td>是</td></tr><tr><td><code>/version</code></td><td>—</td><td>显示 Kimi Code CLI 版本号</td><td>是</td></tr><tr><td><code>/feedback</code></td><td>—</td><td>提交反馈，可附加诊断日志和代码库上下文</td><td>是</td></tr></tbody></table><h2 id="退出" tabindex="-1">退出 <a class="header-anchor" href="#退出" aria-label="Permalink to “退出”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>别名</th><th>说明</th><th>随时可用</th></tr></thead><tbody><tr><td><code>/exit</code></td><td><code>/quit</code>、<code>/q</code></td><td>退出 Kimi Code CLI</td><td>否</td></tr></tbody></table><h2 id="内置-skill-命令" tabindex="-1">内置 Skill 命令 <a class="header-anchor" href="#内置-skill-命令" aria-label="Permalink to “内置 Skill 命令”">​</a></h2><p>Kimi Code CLI 随包内置了一组 Skill，直接以 <code>/&lt;name&gt;</code> 形式出现在斜杠命令面板中。与外部 Skill 不同，它们不需要 <code>skill:</code> 前缀，开箱即用。</p><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/mcp-config</code></td><td>配置 MCP server 并处理 MCP OAuth 登录。详见 <a href="/code/docs/kimi-code-cli/customization/mcp.html">MCP</a></td></tr><tr><td><code>/custom-theme [&lt;text&gt;]</code></td><td>创建或编辑自定义 TUI 配色主题。详见 <a href="/code/docs/kimi-code-cli/customization/themes.html">主题</a></td></tr><tr><td><code>/update-config</code></td><td>查看或编辑 <code>config.toml</code>（模型、供应商、权限、hooks）和 <code>tui.toml</code>（主题、编辑器、通知、自动更新）</td></tr><tr><td><code>/check-kimi-code-docs</code></td><td>依据官方文档回答 Kimi Code 产品问题（CLI 用法、配置、会员、错误码）</td></tr><tr><td><code>/import-from-cc-codex</code></td><td>从 Claude Code 和 Codex 导入 instructions、skills 和 MCP 设置</td></tr><tr><td><code>/sub-skill</code></td><td>发现并将本地 skill 库存重组为分层子 skill 包。包含 <code>/sub-skill.review</code>（只读提案）和 <code>/sub-skill.consolidate</code>（执行重组）</td></tr></tbody></table><p>所有内置 Skill 命令仅在空闲状态下可用。</p><h2 id="skill-动态命令" tabindex="-1">Skill 动态命令 <a class="header-anchor" href="#skill-动态命令" aria-label="Permalink to “Skill 动态命令”">​</a></h2><p>已激活的外部 Skill 会自动注册为斜杠命令。普通外部 Skill 以 <code>skill:</code> 作为命名空间前缀：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/skill:&lt;name&gt; [附加文本]</span></span></code></pre></div><p>例如 <code>/skill:code-style</code> 加载名为 <code>code-style</code> 的 Skill 并发送给 Agent；命令后附带的文本拼接到 Skill 提示词之后。</p><p>外部子 Skill 会直接以点分名称出现在斜杠命令面板中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/&lt;parent-skill&gt;.&lt;sub-skill&gt; [附加文本]</span></span></code></pre></div><p>例如，父 Skill 名为 <code>code-style</code>，其中子 Skill 的本地名称为 <code>review</code>，面板中显示为 <code>/code-style.review</code>。点分命令名由层级自动生成，子 Skill 的 <code>SKILL.md</code> 可以保留本地 <code>name</code>。</p><p>为方便输入，外部 Skill 命令同时支持省略 <code>skill:</code> 前缀的简写形式 <code>/&lt;name&gt;</code>，前提是该名称未被系统斜杠命令占用——即 <code>/code-style</code> 会回退匹配到 <code>/skill:code-style</code>。</p><p>Kimi Code CLI 随包内置的 Skill 会直接以 <code>/&lt;name&gt;</code> 形式出现在斜杠命令面板中。例如，<code>/mcp-config</code> 用于配置 MCP server 和处理 MCP OAuth 登录，<code>/custom-theme [附加文本]</code> 用于进入自定义主题流程，创建或编辑 TUI 主题。</p><div class="info custom-block"><p class="custom-block-title">说明</p><p>所有 Skill 命令仅在空闲状态下可用。<code>flow</code> 类型的 Skill 同样通过 <code>/skill:&lt;name&gt;</code> 暴露，没有独立的 <code>/flow:</code> 命名空间。</p></div><p>Skill 的安装与编写详见 <a href="/code/docs/kimi-code-cli/customization/skills.html">Agent Skills</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/reference/keyboard.html">键盘快捷键</a> — TUI 键盘操作速查</li><li><a href="/code/docs/kimi-code-cli/reference/tools.html">内置工具</a> — Agent 可调用的工具完整参考</li></ul>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};